//! Parity with the TypeScript engine: `engine.cases.json` holds its outputs (outlines, key chords and
//! the operation sequence each action sends to a scripted page), regenerated by
//! `scripts/build-page-function-registry.ts`.
use super::{keys, page, refs::RefTable, snapshot};
use serde_json::{json, Value};
use std::cell::RefCell;

fn cases() -> Value {
    serde_json::from_str(include_str!(
        "../../../../server/src/automation/page/engine.cases.json"
    ))
    .unwrap()
}

/// JSON numbers compared by value (`60` and `60.0` are the same CDP coordinate).
fn numeric(value: &Value) -> Value {
    match value {
        Value::Number(n) => json!(n.as_f64().unwrap()),
        Value::Array(items) => Value::Array(items.iter().map(numeric).collect()),
        Value::Object(map) => {
            Value::Object(map.iter().map(|(k, v)| (k.clone(), numeric(v))).collect())
        }
        other => other.clone(),
    }
}

#[test]
fn outlines_match_the_reference() {
    let cases = cases();
    for case in cases["snapshots"].as_array().unwrap() {
        let nodes = cases["pages"][case["page"].as_str().unwrap()]
            .as_array()
            .unwrap();
        let options = snapshot::Options {
            root: case["options"]["rootBackendNodeId"].as_u64(),
            query: case["options"]["query"].as_str(),
            budget: case["options"]["budget"].as_u64().map(|b| b as usize),
        };
        let mut issue = |node: u64| format!("e{node}");
        let label = format!("{} {}", case["page"], case["options"]);
        match snapshot::render(nodes, &mut issue, &options) {
            Ok(out) => {
                assert_eq!(out.text, case["text"].as_str().unwrap(), "{label}");
                assert_eq!(
                    out.collapsed as u64,
                    case["collapsed"].as_u64().unwrap(),
                    "{label}"
                );
            }
            Err(snapshot::Gone) => assert!(case["error"].is_string(), "{label}"),
        }
    }
}

#[test]
fn chords_match_the_reference() {
    for case in cases()["keys"].as_array().unwrap() {
        let mac = case["platform"] == "darwin";
        let label = format!("{} {}", case["chord"], case["platform"]);
        match keys::chord(case["chord"].as_str().unwrap(), mac) {
            Ok(events) => assert_eq!(numeric(&json!(events)), numeric(&case["events"]), "{label}"),
            Err(error) => assert_eq!(json!(error), case["error"], "{label}"),
        }
    }
}

/// The reference's scripted page (`engine-cases.ts`): boxes per node, an overlay over node 13.
fn scripted(nodes: &Value, operation: &Value) -> Value {
    let rect = |node: u64| {
        (node != 14).then(|| {
            (
                20.0 + (node % 7) as f64 * 100.0,
                40.0 + node as f64 * 20.0,
                80.0,
                16.0,
            )
        })
    };
    let handle = operation["handle"].as_str().unwrap_or("");
    match operation["op"].as_str().unwrap() {
        "tree" => json!({"nodes": nodes}),
        "geometry" => match rect(operation["node"].as_u64().unwrap()) {
            Some((x, y, w, h)) => json!({"quads": [[x, y, x + w, y, x + w, y + h, x, y + h]]}),
            None => json!({"quads": []}),
        },
        "viewport" => json!({"width": 800, "height": 600}),
        "hit-test" => {
            let (px, py) = (
                operation["x"].as_f64().unwrap(),
                operation["y"].as_f64().unwrap(),
            );
            let hit = [10, 11, 12, 13, 15, 16].into_iter().find(|id| {
                let (x, y, w, h) = rect(*id).unwrap();
                px >= x && px < x + w && py >= y && py < y + h
            });
            match hit {
                Some(13) => json!({"node": 11}),
                Some(node) => json!({"node": node}),
                None => json!({}),
            }
        }
        "call" => match operation["function"].as_str().unwrap() {
            "option-click" if handle == "h15" => json!({"value": ["Pro"]}),
            "option-click" if handle == "h14" => {
                json!({"exception": "Error: codenomad:is-select\n    at <anonymous>"})
            }
            "field" => json!({"handle": format!("f{handle}")}),
            "prepare" if handle == "fh16" => json!({"value": "append"}),
            "prepare" if handle == "fh10" => json!({"exception": "Error: codenomad:not-text"}),
            "prepare" => json!({"value": "insert"}),
            "read-value" => json!({"value": "typed"}),
            "select" if handle == "h13" => json!({"exception": "Error: codenomad:no-option:Gold"}),
            "select" => json!({"value": ["Pro"]}),
            "receives" => json!({"value": "div \"Overlay\""}),
            "describe" => json!({"value": "textbox \"Name\""}),
            "active-element" => json!({"handle": "active"}),
            "document-root" => json!({"handle": "document"}),
            "contains" => json!({"value": operation["args"][0] == "Save"}),
            "input-acceptance" => json!({"value": {"inputDelayMs": 0}}),
            "mark-input" => json!({"value": 1_700_000_000.5}),
            "unmark-input" => json!({"value": true}),
            "focus" if handle == "h10" => json!({"exception": "Error: codenomad:unfocusable"}),
            _ => json!({"value": null}),
        },
        _ => json!({}),
    }
}

#[test]
fn actions_send_the_reference_operations() {
    let cases = cases();
    let nodes = &cases["pages"]["fixture"];
    for case in cases["actions"].as_array().unwrap() {
        let log = RefCell::new(Vec::new());
        let send = |operation: Value| {
            log.borrow_mut().push(operation.clone());
            if operation["op"] == "resolve" && operation["node"] == 999 {
                return Err("No node with given id".to_string());
            }
            Ok(match operation["op"].as_str() {
                Some("resolve") => json!({"handle": format!("h{}", operation["node"])}),
                _ => scripted(nodes, &operation),
            })
        };
        let checkpoint = || {
            log.borrow_mut().push(json!({"checkpoint": true}));
            Ok(())
        };
        let session = page::Session {
            driver: "cdp",
            send: &send,
            checkpoint: &checkpoint,
            mark: case["mark"] == true,
        };
        let resolve = |reference: &str| Ok(reference[1..].parse::<u64>().unwrap());
        let label = format!("{} mark={}", case["action"], case["mark"]);
        match page::act(&session, &case["action"], &resolve) {
            Ok(mut result) => {
                if result.get("waitedMs").is_some() {
                    result["waitedMs"] = json!(0);
                }
                assert_eq!(numeric(&result), numeric(&case["result"]), "{label}");
            }
            Err(fail) => assert_eq!(json!(fail.message), case["error"], "{label}"),
        }
        assert_eq!(
            numeric(&json!(*log.borrow())),
            numeric(&case["operations"]),
            "{label}"
        );
    }
}

#[test]
fn snapshots_issue_refs_per_generation_and_report_a_departed_scope() {
    let cases = cases();
    let nodes = cases["pages"]["fixture"].clone();
    let send = |_: Value| Ok(json!({"nodes": nodes}));
    let checkpoint = || Ok(());
    let session = page::Session {
        driver: "cdp",
        send: &send,
        checkpoint: &checkpoint,
        mark: true,
    };
    let mut refs = RefTable::new("inspect again", "e");
    let (text, _) = page::snapshot(&session, &mut refs, "g1", &json!({}), true).unwrap();
    assert!(
        text.starts_with("- heading \"Checkout\" [e1] level=2"),
        "{text}"
    );
    let (scoped, _) =
        page::snapshot(&session, &mut refs, "g1", &json!({"ref": "e5"}), true).unwrap();
    assert!(
        scoped.starts_with("- combobox \"Plan\" [e5]\n  - option \"Pro\" [e6]"),
        "{scoped}"
    );
    let stale = page::snapshot(&session, &mut refs, "g2", &json!({"ref": "e5"}), true).unwrap_err();
    assert_eq!(stale.message, "Unknown or stale ref e5; inspect again");
}
